"""Rows of earlier versions, generated by shape, and today's remask and readers over them.

Each case is one item, written one of two ways. An earlier version of today's mask() wrote it and recorded that
version on its rows, as a later version will find this one's: its own mask's output, or in the worst case its text as it
came. Or an older kb wrote it, before rows recorded a version: main's store_item with main's own mask()
(tests/legacy_mask.py), its token patterns alone or no mask at all, sometimes main's row-by-row remask after it, and
summary rows as main's summarizer wrote them, cut before they were masked. Main wrote a tool's input as JSON and cut it
to 300 characters before masking it. An item's id is a note filed under a name with a secret-looking word, a Hermes
session in a profile with or without one, a session id, or now and then a name that holds a real secret. Its text
holds filler, tokens, named values and private keys in the layouts text gives them, whole or cut before the footer.

After today's remask, on every case: an earlier version's item whose id holds no secret keeps every kind of row it
had, and one whose id holds one is gone; no row of an earlier version is left old; and no row stamped current holds a
piece of a planted secret, read through the layout's marks. An older kb's rows are left as they were and never stamped,
search shows none of them, and the store refuses to open again until it is rebuilt. KB_OLD_ROW_CASES sets the number
of cases and KB_OLD_ROW_SEED the seed.
"""
import json
import os
import random
import re
import tempfile
import unittest

from kb import search, store
from kb.mask import VERSION, mask
from tests import legacy_mask, legacy_store
from tests.test_write_fuzz import BASE64, KEY_STARTS

CASES = int(os.environ.get("KB_OLD_ROW_CASES", "1500"))
SEED = os.environ.get("KB_OLD_ROW_SEED", "20261101")
ITEMS_PER_STORE = 40
CHUNK = 160
TS = "2026-10-01T10:00:00Z"
FILLER = ("walrus", "ledger", "deploy", "notes", "harbor", "the", "plan", "moved", "today", "approved")
# Names with a secret-looking word in them that hold no secret.
NOTE_NAMES = ("Courses/Basic Statistics/lecture-01.md", "Wedding/Ring Bearer duties/plan-2026.md",
              "ML/sk-learn-pipeline-experiments.md", "Security/password manager migration 2026-10.md",
              "Tokens: 2026Q4 plan.md", "api_key rotation.md", "Session token expiry bug.md", "secret-santa-2026.md",
              "token-economics/notes.md", "Areas/Secrets: rotation plan.md", "Basic Kubernetes101.md")
PROFILES = ("default", "work", "secret-project", "token-research", "api-keys", "my-passwords", "auth-team")
# Names that hold a real secret, which no store may keep.
SECRET_NAMES = ("key-sk-ant-api03-" + "Z" * 24 + ".md", "password=walrus2secret9.md", "ghp_" + "A1" * 18 + ".md")
KEY_KINDS = ("PRIVATE KEY", "RSA PRIVATE KEY", "EC PRIVATE KEY", "OPENSSH PRIVATE KEY")
LAYOUTS = ("plain", "crlf", "escaped", "json in json", "a string a line", "a string a line in JSON", "# comments",
           "> quotes", "<br> breaks")
# Named values on lines of their own, in the forms a config, a shell script or a request writes them.
NAMED = ("db_password: {}", "api_key: {}", "Authorization: Token {}", "export REDIS_PASSWORD={}", "redis-cli -a {} ping",
         "curl -u bob:{} https://api.example.com", "secret_token = '{}'", "mysql -u root -p{} shop", "--api-key {}",
         ':password => "{}"', "X-Api-Key: {}")
# The marks a layout puts around a key's lines, which a reader looks through.
MARKS = re.compile(r"\s+|\\+[nrt]|<br>|[\"'#>+]")


class Case:
    """One item as an older kb stored it, and the secrets planted in it."""

    def __init__(self, r, n):
        self.r, self.n, self.pieces = r, n, set()
        self.source, self.sid, self.meta, self.secret_id = self._name()
        self.text = r.choice((" ", "\n")).join(self._part() for _ in range(r.randint(1, 5)))

    def _name(self):
        r = self.r
        pick = r.random()
        if pick < 0.08:
            return "notes", f"desk:{self.n}/{r.choice(SECRET_NAMES)}", {"path": "/notes/x.md", "host": "desk"}, True
        if pick < 0.45:
            name = f"{r.choice(NOTE_NAMES)[:-3]}-{self.n}.md"
            return "notes", f"desk:{name}", {"path": f"/notes/{name}", "host": "desk"}, False
        if pick < 0.85:
            profile, session = r.choice(PROFILES), f"20261028_1015{self.n % 100:02d}_a{self.n:05x}"
            meta = {"path": f"/hermes/{profile}/state.db#{session}", "profile": profile, "platform": "cli",
                    "session_id": session, "host": "desk"}
            return "hermes", f"desk:{profile}:{session}", meta, False
        return "claude_code", f"desk:3f1c2d4e-0000-4000-8000-{self.n:012x}", {"path": "/cc/s.jsonl", "host": "desk"}, False

    def _value(self, shape):
        value = shape.format(f"{self.n:05d}{len(self.pieces):03d}")
        self.pieces.update(value[i:i + 14] for i in range(0, len(value) - 13, 4))
        return value

    def _part(self):
        pick = self.r.random()
        if pick < 0.35:
            return " ".join(self.r.choice(FILLER) for _ in range(self.r.randint(3, 25)))
        if pick < 0.45:
            return self._value("sk-ant-api03-old{}" + "Q" * 20)
        if pick < 0.6:
            return "\n".join(self.r.choice(NAMED).format(self._value("Zq{}Wm4Np8Rt2Kd9")) for _ in range(self.r.randint(1, 4)))
        return self._key()

    def _key(self):
        r = self.r
        kind = r.choice(KEY_KINDS)
        start = r.choice(KEY_STARTS[kind])
        body = start + "".join(r.choice(BASE64) for _ in range(r.randint(40, 300)))
        width = r.randint(64, 76)
        lines = [body[i:i + width] for i in range(0, len(body), width)]
        whole = r.random() < 0.5
        if not whole:
            lines[-1] = lines[-1][:r.randint(1, len(lines[-1]))]
        self.pieces.update(body[i:i + 14] for i in range(0, len(body) - 13, 7) if i + 14 <= len("".join(lines)))
        head, foot = f"-----BEGIN {kind}-----", f"-----END {kind}-----"
        block = [head, *lines] + ([foot] if whole else [])
        layout = r.choice(LAYOUTS)
        if layout == "plain":
            return "\n".join(block)
        if layout == "crlf":
            return "\r\n".join(block)
        if layout == "escaped":
            return '{"key": "' + "\\n".join(block) + '"}'
        if layout == "json in json":
            return '{\\"private_key\\":\\"' + "\\\\n".join(block) + '\\"}'
        if layout == "a string a line":
            return 'key = (\n    "' + '\\n"\n    "'.join(block) + '"\n)'
        if layout == "a string a line in JSON":
            return '{"output": "var key = \\"' + '\\n\\" +\\n\\t\\"'.join(block) + '\\""}'
        if layout == "# comments":
            return "# " + "\n# ".join(block)
        if layout == "> quotes":
            return "> " + "\n> ".join(block)
        return "<br>".join(block)


def write(db, r, case):
    """The case's rows as an earlier version of today's mask wrote them, or as an older kb did."""
    case.older = r.random() < 0.5
    if case.older:
        pick = r.random()
        masker = legacy_mask.mask if pick < 0.6 else legacy_store.token_mask if pick < 0.85 else (lambda text: text)
    else:
        masker = mask if r.random() < 0.6 else (lambda text: text)
    text = case.text
    if r.random() < 0.4:  # a tool's input as a reader wrote it: JSON, which main cut to 300 characters before masking
        text = json.dumps({"body": text}, ensure_ascii=False)
        text = text if case.older else mask(text)  # this branch's readers mask a tool's input before they cut it
        text = "TOOL mcp__notes__create: " + (text if len(text) <= 300 else text[:300] + " …")
    legacy_store.store_item(db, case.source, case.sid, TS, f"title {case.n}", text, case.meta, CHUNK, masker)
    if r.random() < 0.4:  # summaries, recording only url, path and host as main's did
        meta = {k: case.meta[k] for k in ("url", "path", "host") if k in case.meta}
        question, summary = case.text[:r.randint(20, 600)], case.text[:r.randint(20, 1800)]
        if case.older:  # main cut each field before masking it
            rows = [("segment", "What shipped", masker(f"{question[:400]}\n{summary[:1500]}")),
                    ("atom", "fact: what shipped", masker(case.text[:2000]))]
        else:  # a summarizer sends the model the item masked, and masks each field before it cuts it
            seen = mask(case.text)
            rows = [("segment", "What shipped", f"{mask(seen[:len(question)])[:400]}\n{mask(seen[:len(summary)])[:1500]}"),
                    ("atom", "fact: what shipped", mask(seen)[:2000])]
        db.executemany("INSERT INTO docs(kind, source, source_id, ts, title, content, metadata) VALUES (?,?,?,?,?,?,?)",
                       [(kind, case.source, case.sid, TS, title, content, json.dumps({**meta, "of_hash": "3f"}))
                        for kind, title, content in rows])
    db.execute("UPDATE docs SET masked=? WHERE source=? AND source_id=?",
               (None if case.older else "0123456789abcdef", case.source, case.sid))


def problems(db, path, cases):
    found = []
    for case in cases:
        rows = db.execute("SELECT id, kind, masked, content FROM docs WHERE source=? AND source_id=?",
                          (case.source, case.sid)).fetchall()
        kinds = {kind for _, kind, _, _ in rows}
        if case.older:
            if case.kinds - kinds:
                found.append(f"{case.sid!r}: an older kb's item lost its {sorted(case.kinds - kinds)} rows")
            if {(rid, content) for rid, _, version, content in rows if version is None} != case.unversioned:
                found.append(f"{case.sid!r}: an older kb's row was changed or stamped with a version")
        elif case.secret_id:
            if kinds:
                found.append(f"{case.sid!r}: kept, though its id holds a secret")
        elif case.kinds - kinds:
            found.append(f"{case.sid!r}: lost its {sorted(case.kinds - kinds)} rows, though its id holds no secret")
    old = db.execute("SELECT count(*) FROM docs r WHERE r.masked IS NOT NULL AND r.masked != ? AND NOT EXISTS "
                     "(SELECT 1 FROM docs n WHERE n.source = r.source AND n.source_id = r.source_id AND n.masked IS NULL)",
                     (VERSION,)).fetchone()[0]
    if old:
        found.append(f"{old} rows left old")
    for sid, kind, masked, text in db.execute("SELECT source_id, kind, masked, title || content || metadata FROM docs"):
        if masked != VERSION:
            continue
        readable = MARKS.sub("", text)
        leaked = sorted(p for case in cases for p in case.pieces if MARKS.sub("", p) in readable)
        if leaked:
            found.append(f"{sid!r} {kind} is current and shows {leaked[0]!r}")
    pieces = {MARKS.sub("", p) for case in cases for p in case.pieces}
    for query in ("walrus ledger", "deploy notes", "harbor plan", "api_key", "password", "PRIVATE KEY"):
        for hit in search.search(db, query, limit=100):
            readable = MARKS.sub("", "".join((hit["title"], hit["snippet"], hit["excerpt"], hit["content"])))
            shown = sorted(p for p in pieces if p in readable)
            if shown:
                found.append(f"search for {query!r} shows {shown[0]!r} in {hit['source_id']!r}")
    if any(case.older for case in cases):
        try:
            store.connect(path).close()
            found.append("a store with an older kb's rows opened")
        except store.NeedsRebuild:
            pass
    return found


def run(cases=CASES):
    failures = []
    with tempfile.TemporaryDirectory() as root:
        for first in range(0, cases, ITEMS_PER_STORE):
            db = store.connect(os.path.join(root, f"{first}.sqlite"))
            db.execute("PRAGMA synchronous=OFF")  # a scratch file: no write here needs to survive a power cut
            batch = []
            for n in range(first, min(first + ITEMS_PER_STORE, cases)):
                r = random.Random(f"{SEED}:{n}")
                case = Case(r, n)
                write(db, r, case)
                case.kinds = {k for (k,) in db.execute("SELECT DISTINCT kind FROM docs WHERE source=? AND source_id=?",
                                                       (case.source, case.sid))}
                batch.append(case)
            if random.Random(f"{SEED}:remask:{first}").random() < 0.5:
                legacy_store.remask(db, legacy_store.token_mask)  # main's own remask, a row at a time
            db.commit()
            for case in batch:  # what main's remask changed is an older kb's row now, whichever wrote it first
                case.unversioned = set(db.execute("SELECT id, content FROM docs WHERE source=? AND source_id=? AND "
                                                  "masked IS NULL", (case.source, case.sid)).fetchall())
                case.older = bool(case.unversioned)
            store.remask(db)
            failures += problems(db, os.path.join(root, f"{first}.sqlite"), batch)
            db.close()
    return failures


class OldRowShapeTest(unittest.TestCase):
    def test_remask_keeps_every_item_without_a_secret_stamps_no_row_with_one_and_reads_no_older_kbs(self):
        failures = run()
        self.assertEqual(failures, [], f"{len(failures)} problems in {CASES} cases (KB_OLD_ROW_SEED={SEED}); "
                                       f"the first: {failures[:3]}")


if __name__ == "__main__":
    unittest.main()
